#define assert(value) ((void)0)

class FEMenu;

class FEMenuEntry
{
public:
    int entry_num;
    FEMenuEntry* next;
    FEMenuEntry* previous;
    FEMenu* menu;

    virtual ~FEMenuEntry();
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool h = true, bool anim = true);
    virtual void Disable(bool d = true);
    virtual bool GetDisable();
};

enum {
    FEMENU_SCROLLING = 0x001,
    FEMENU_WRAP = 0x002,
    FEMENU_DONT_SKIP_DISABLED = 0x040,
    FEMENU_DONT_SHOW_DISABLED = 0x400,
};

class FEMenu
{
    char padding_to_flags[0x38];

public:
    int flags;
    FEMenuEntry* entries;
    FEMenuEntry* first_vis_entry;
    FEMenuEntry* last_vis_entry;
    FEMenuEntry* highlighted;

    virtual ~FEMenu();
    virtual void setBack(FEMenu* b, int bn = 1);
    virtual void setHigh(FEMenuEntry* menu, bool anim = true);
    virtual void setVis(FEMenuEntry* first);
    virtual void Add(FEMenuEntry* e);
    virtual void Init();
    virtual void Load(bool floating);
    virtual void Load();
    virtual void Draw();
    virtual void DrawTop();
    virtual void UpdateInScene();
    virtual void Update(float time_inc);
    virtual void HighlightDefault(void);
    virtual void OnActivate();
    virtual void OnActivate(int sub_menu);
    virtual void OnUnactivate(FEMenu* m);
    virtual void OnSelect(int c);
    virtual void OnStart(int c);
    virtual void OnUp(int c);
    virtual void OnDown(int c);
    virtual void OnLeft(int c);
    virtual void OnRight(int c);
    virtual void OnCross(int c);
    virtual void OnTriangle(int c);
    virtual void OnSquare(int c);
    virtual void OnCircle(int c);
    virtual void OnL1(int c);
    virtual void OnR1(int c);
    virtual void OnL2(int c);
    virtual void OnR2(int c);
    virtual void OnAnyButtonPress(int c, int b);
    virtual void OnButtonRelease(int c, int b);
    virtual void SetAllScale(float s);
    virtual void MakeActive(FEMenu* a);
    virtual void SetHelpText(const int hFlags);
    virtual void Select(int entry_num);

protected:
    virtual void cons(void* s, int x, int y, int mve = 8);
    virtual void cons(void* s, int x, int y, unsigned int ch, unsigned int cha, int mve = 8);
    virtual void cons(void* s, int x, int y, unsigned int c, unsigned int ch, unsigned int cha, float sc = 1.0, float sch = 1.2, int mve = 8, int flg = 0);
    virtual void Next();
    virtual void Previous();
    virtual void Select();
    virtual void AddSubmenu(FEMenu* sub);
};

void FEMenu::Previous()
{
    assert(highlighted);
    if(!(flags & FEMENU_WRAP) && highlighted == entries) return;
    if((flags & FEMENU_SCROLLING) && highlighted == first_vis_entry)
    {
        FEMenuEntry* first = first_vis_entry->previous;
        if(flags & FEMENU_DONT_SHOW_DISABLED)
        {
            while(first->GetDisable() && first != highlighted)
                first = first->previous;
        }
        setVis(first);
    }

    FEMenuEntry* tmp = highlighted->previous;
    if(tmp)
    {
        if(!(flags & FEMENU_DONT_SKIP_DISABLED))
            while(tmp->GetDisable() && tmp != highlighted) tmp = tmp->previous;
            setHigh(tmp);
    }
}
